                writer.WriteString("mailboxPoolId", mailPostCadenceRunsRequest.MailboxPoolId);

            if (mailPostCadenceRunsRequest.ScheduledAtOption.IsSet)
                writer.WriteString("scheduledAt", mailPostCadenceRunsRequest.ScheduledAtOption.Value!.Value.ToString(ScheduledAtFormat));
        }
    }
}
